with c as (select id from public.academy_courses where id='meteorology-forecasting-foundations'),
ch as (insert into public.academy_chapters(course_id,title,description,sort_order,published) select id,'فيزياء السحب والميكروفيزياء والهطول','تكوين قطرات السحب والعمليات الدافئة والجليدية وتفاعلات الهباء وميكروفيزياء الهطول وتمثيلها في النماذج والتحقق منها رصدياً.',59,false from c on conflict(course_id,title) do update set description=excluded.description returning id),
u1 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'تكوين القطرات والسحب الدافئة',1,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
u2 as (insert into public.academy_units(chapter_id,title,sort_order,published) select id,'الجليد السحابي والهطول والتحقق الرصدي',2,false from ch on conflict(chapter_id,title) do update set sort_order=excluded.sort_order returning id),
d(slug,title,summary,content,ord,mins,objectives,unit_title) as (values
('cloud-condensation-nuclei','نوى تكاثف السحب','الهباء الجوي والتنشيط وتوزيع أحجام القطرات','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تبدأ قطرات السحب غالباً على جسيمات هباء تعمل نوى تكاثف. يتوقف التنشيط على الرطوبة الفائقة وحجم الجسيم وتركيبه الكيميائي والتوتر السطحي، لذلك يؤثر الهباء في عدد القطرات وخصائص السحابة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"نوى تكاثف السحب","text":"اربط بين زيادة عدد النوى وتغير عدد القطرات ومتوسط حجمها. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اربط بين زيادة عدد النوى وتغير عدد القطرات ومتوسط حجمها."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,7960,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'تكوين القطرات والسحب الدافئة'),
('kohler-theory','نظرية كوهلر لنمو قطرات السحب','توازن أثر الانحناء والذوبانية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تشرح نظرية كوهلر اعتماد ضغط البخار فوق القطرة على نصف قطرها وتركيبها، وتجمع بين أثر كلفن وأثر المذاب. تحدد القمة الحرجة شروط تنشيط نواة الهباء إلى قطرة سحابية."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"نظرية كوهلر لنمو قطرات السحب","text":"فسر نوعياً كيف يغير المذاب نصف القطر الحرج والرطوبة الفائقة اللازمة. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر نوعياً كيف يغير المذاب نصف القطر الحرج والرطوبة الفائقة اللازمة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,7970,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'تكوين القطرات والسحب الدافئة'),
('cloud-droplet-size-distribution','توزيع أحجام قطرات السحب','العرض الطيفي والتطور الميكروفيزيائي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"لا تتساوى قطرات السحب في الحجم؛ يوصف المجتمع بتوزيع عددي أو كتلي. يؤثر عرض التوزيع في التصادم والالتحام والتبخر والخصائص البصرية للسحابة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"توزيع أحجام قطرات السحب","text":"قارن توزيعاً ضيقاً وآخر واسعاً من حيث فرص التصادم. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن توزيعاً ضيقاً وآخر واسعاً من حيث فرص التصادم."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,7980,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'تكوين القطرات والسحب الدافئة'),
('condensation-growth-kinetics','حركية نمو القطرات بالتكاثف','انتقال الحرارة وبخار الماء','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينمو قطر القطرة عندما ينتقل إليها بخار الماء وتزال الحرارة الكامنة الناتجة. تتباطأ عملية النمو مع ازدياد الحجم وتخضع لمقاومة انتقال الكتلة والحرارة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"حركية نمو القطرات بالتكاثف","text":"اشرح لماذا لا يستمر نمو القطرات بالتكاثف بالمعدل نفسه مع الزمن. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح لماذا لا يستمر نمو القطرات بالتكاثف بالمعدل نفسه مع الزمن."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,7990,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'تكوين القطرات والسحب الدافئة'),
('collision-coalescence','التصادم والالتحام في السحب الدافئة','الكفاءة الحركية وتطور المطر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتولد قطرات أكبر عندما تصطدم قطرات مختلفة السرعة والحجم وتلتحم. تعتمد العملية على كفاءة التصادم والالتحام واتساع توزيع الأحجام وعمق السحابة ومدة بقائها."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التصادم والالتحام في السحب الدافئة","text":"اشرح كيف يساهم اتساع توزيع الأحجام في بدء المطر الدافئ. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح كيف يساهم اتساع توزيع الأحجام في بدء المطر الدافئ."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8000,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'تكوين القطرات والسحب الدافئة'),
('warm-rain-initiation','بدء الهطول في السحب الدافئة','من قطرات السحب إلى قطرات المطر','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتطلب تكوين المطر الدافئ انتقال جزء من القطرات الدقيقة إلى أحجام أكبر عبر التصادم والالتحام. تؤثر خصائص السحابة والهباء والتيارات الصاعدة في زمن بدء الهطول."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"بدء الهطول في السحب الدافئة","text":"قارن بيئة سحابية ذات قطرات متقاربة الحجم وأخرى متعددة الأحجام. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن بيئة سحابية ذات قطرات متقاربة الحجم وأخرى متعددة الأحجام."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8010,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'تكوين القطرات والسحب الدافئة'),
('ice-nucleation-pathways','مسارات تنوي الجليد في السحب','التنوي المتجانس وغير المتجانس','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يتشكل الجليد في السحب عبر مسارات متعددة تشمل التنوي غير المتجانس على جسيمات نوى جليدية والتنوي المتجانس في ظروف حرارية مناسبة. تختلف كفاءة النوى باختلاف تركيبها وحرارتها ورطوبتها."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"مسارات تنوي الجليد في السحب","text":"صنف مسارات التنوي ووضح دور الجسيمات النشطة جليدياً. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"صنف مسارات التنوي ووضح دور الجسيمات النشطة جليدياً."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8020,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
('ice-crystal-habit','أشكال بلورات الجليد السحابية','اعتماد الشكل على الحرارة والإشباع','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتخذ بلورات الجليد أشكالاً مختلفة مثل الصفائح والأعمدة والتراكيب المتفرعة. يرتبط الشكل بدرجة الحرارة وفرط الإشباع ببخار الماء والمدة وظروف النمو الدقيقة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"أشكال بلورات الجليد السحابية","text":"فسر لماذا لا يكفي عامل الحرارة وحده لتحديد شكل البلورة. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر لماذا لا يكفي عامل الحرارة وحده لتحديد شكل البلورة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8030,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
('bergeron-findeisen-process','عملية بيرجيرون–فيندايزن','نمو الجليد على حساب قطرات الماء الفائق التبريد','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينشأ نمو بلورات الجليد في سحب مختلطة الطور من اختلاف ضغط البخار المشبع فوق الماء والجليد. قد ينتقل بخار الماء من القطرات فائقة التبريد إلى البلورات، فتزداد كتلة الجليد."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"عملية بيرجيرون–فيندايزن","text":"اشرح اتجاه انتقال بخار الماء في سحابة مختلطة الطور. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"اشرح اتجاه انتقال بخار الماء في سحابة مختلطة الطور."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8040,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
('riming-and-aggregation','التجمد بالاصطدام والتجمع البلوري','تكوين الحبيبات والثلج','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"ينمو الجليد بالـriming عندما تتجمد قطرات فائقة التبريد على البلورة، وبالتجمع عندما تلتصق البلورات ببعضها. تؤثر الحرارة ومحتوى الماء السائل وحجم البلورات في نوع الجسيم الناتج."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"التجمد بالاصطدام والتجمع البلوري","text":"ميز بين أثر التصادم بقطرات سائلة وأثر تصادم بلورات جليدية. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ميز بين أثر التصادم بقطرات سائلة وأثر تصادم بلورات جليدية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8050,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
('graupel-hail-microphysics','ميكروفيزياء الحبيبات الثلجية والبرد','التجمد وتراكم الماء داخل السحب الحملية','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتكون الحبيبات الثلجية والبرد عبر مسارات نمو جليدي تختلف في مقدار الماء المتجمد وطبيعة النمو والبيئة الحملية. يتطلب التمييز بينها تحليل البنية والكثافة والطبقات وظروف السحابة."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"ميكروفيزياء الحبيبات الثلجية والبرد","text":"قارن السمات الميكروفيزيائية العامة للحبيبات الثلجية والبرد. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن السمات الميكروفيزيائية العامة للحبيبات الثلجية والبرد."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8060,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
('precipitation-particle-melting','انصهار جسيمات الهطول أثناء السقوط','الطبقة الدافئة والملف الحراري الرأسي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"تتغير حالة جسيمات الهطول أثناء عبورها طبقات جوية مختلفة الحرارة. يتوقف الانصهار على عمق الطبقة الدافئة وحرارتها ورطوبتها وحجم الجسيم وسرعة سقوطه."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"انصهار جسيمات الهطول أثناء السقوط","text":"حلل مقطعاً رأسياً افتراضياً يضم طبقة متجمدة وأخرى دافئة. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"حلل مقطعاً رأسياً افتراضياً يضم طبقة متجمدة وأخرى دافئة."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط ال