('evaporation-sublimation-virga','تبخر الهطول وتسامي الجليد والفيرغا','تبريد الهواء وتعديل الطبقة السفلى','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"قد يتبخر المطر أو يتسامى الجليد قبل بلوغ السطح عندما تكون الطبقة السفلى غير مشبعة. يؤدي ذلك إلى تبريد تبخري وتغير الرطوبة والاستقرار، وقد يظهر الهطول المعلق بصرياً دون وصوله للأرض."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"تبخر الهطول وتسامي الجليد والفيرغا","text":"فسر كيف يمكن لهطول مرئي من السحابة ألا يصل إلى مقياس المطر. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"فسر كيف يمكن لهطول مرئي من السحابة ألا يصل إلى مقياس المطر."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8080,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
('terminal-fall-velocity','سرعة السقوط النهائية لجسيمات الهطول','مقاومة الهواء والشكل والكثافة','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"توازن سرعة السقوط النهائية بين الوزن وقوة مقاومة الهواء وقوة الطفو. تختلف السرعة باختلاف الحجم والشكل والكثافة واتجاه الجسيم، ولا يصح تعميم قيمة واحدة على المطر والثلج والبرد."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"سرعة السقوط النهائية لجسيمات الهطول","text":"قارن العوامل المؤثرة في سرعة قطرة مطر وبلورة ثلج. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"قارن العوامل المؤثرة في سرعة قطرة مطر وبلورة ثلج."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8090,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
('cloud-liquid-water-content','المحتوى المائي السائل للسحب','التركيز الكتلي والتوزيع الرأسي','{"blocks":[{"type":"heading","text":"المفهوم العلمي"},{"type":"text","text":"يمثل المحتوى المائي السائل كتلة الماء السائل في وحدة حجم من الهواء. تتغير قيمته رأسياً ومكانياً مع التيارات الصاعدة والتكاثف والتصادم والهطول، ويعد مهماً لفهم نمو السحب."},{"type":"heading","text":"الأساس الفيزيائي"},{"type":"text","text":"تتحكم انتقالات الكتلة والطاقة بين بخار الماء والقطرات والبلورات في تطور السحب. ويجب التمييز بين المتغيرات العددية والكتلية وبين الخصائص المحلية والمتوسطات الحجمية، مع تحديد الطور المائي والظروف الحرارية المحيطة."},{"type":"heading","text":"المتغيرات والقياسات"},{"type":"list","items":["درجة الحرارة والرطوبة والإشباع بالنسبة للماء والجليد.","عدد الجسيمات وتوزيع أحجامها وخصائصها الشكلية.","المحتوى المائي السائل والجليدي والسمك الرأسي للسحابة.","التيارات الرأسية وزمن بقاء الجسيمات ومسارات سقوطها.","خصائص الرصد ودقة الجهاز وحدود الكشف والمعايرة."]},{"type":"heading","text":"منهجية التحليل"},{"type":"list","items":["حدد نوع السحابة والطور والبيئة الحرارية.","حدد المتغيرات الميكروفيزيائية ذات الصلة بالسؤال.","اربط الآلية المجهرية بالتطور السحابي والهطول.","قارن القياسات المتاحة مع مخرجات النموذج.","سجل الافتراضات والقيود ومصادر عدم اليقين."]},{"type":"heading","text":"مثال تطبيقي"},{"type":"example","title":"المحتوى المائي السائل للسحب","text":"ارسم ملفاً رأسياً افتراضياً للمحتوى المائي في سحابة نامية. ابنِ تفسيراً نوعياً أو حسابياً مبسطاً، وحدد البيانات اللازمة للتحقق قبل تعميم النتيجة."},{"type":"heading","text":"المهمة العملية"},{"type":"text","text":"ارسم ملفاً رأسياً افتراضياً للمحتوى المائي في سحابة نامية."},{"type":"heading","text":"أخطاء شائعة"},{"type":"list","items":["الخلط بين عدد الجسيمات وكتلتها الكلية.","افتراض أن كل السحب تتبع آلية ميكروفيزيائية واحدة.","إهمال اعتماد العمليات على الحرارة والإشباع.","مقارنة قياسات غير متزامنة أو مختلفة الحجم المكاني.","اعتبار مخطط النموذج وصفاً كاملاً لكل العمليات المجهرية."]},{"type":"callout","text":"تفسير الهطول يتطلب ربط العمليات الميكروفيزيائية بالبيئة الديناميكية والحرارية للسحابة، لا الاكتفاء بمظهرها الخارجي."},{"type":"heading","text":"الخلاصة"},{"type":"text","text":"تقدم الميكروفيزياء إطاراً لفهم تحول بخار الماء إلى قطرات وبلورات ثم هطول. ويعتمد التقييم العلمي على تكامل النظرية والقياس والرصد عن بعد والنمذجة والتحقق المستقل."}]}'::jsonb,8100,55,'["شرح الآلية الميكروفيزيائية والعمليات المرتبطة بها","تحليل المتغيرات والقياسات اللازمة لتوصيف الظاهرة","تقييم تمثيل العملية في الرصد والنماذج العددية"]'::jsonb,'الجليد السحابي والهطول والتحقق الرصدي'),
